import numpy as np

class NearestCentroidClassifier:
    def fit(self, X, y):
        self.classes_ = np.unique(y)
        self.centroids_ = np.array([X[y == c].mean(axis=0) for c in self.classes_])

    def predict(self, X):
        return np.array([self.classes_[np.argmin(np.linalg.norm(x - self.centroids_, axis=1))] for x in X])
